import numpy as np

def make_prices(seed, n=60):
    """n daily closes of one share, starting near 100p, with 2% daily volatility."""
    rng = np.random.default_rng(seed)
    return list(np.round(100 * np.cumprod(1 + 0.02 * rng.standard_normal(n)), 2))

