import pandas as pd

def centred_vs_trailing(prices, w):
    r = pd.Series(prices, dtype=float).pct_change()
    trailing = r.rolling(w).std()               # window of w returns ending on day t
    centred = r.rolling(w, center=True).std()   # window of w returns centred on day t
    return pd.DataFrame({"trailing": trailing, "centred": centred})

