from sklearn.linear_model import LinearRegression

def leak_score_gap(X_clean, X_leaky, y, n_train):
    scores = []
    for X in (X_clean, X_leaky):
        model = LinearRegression().fit(X[:n_train], y[:n_train])
        r2 = model.score(X[n_train:], y[n_train:])
        scores.append(round(float(r2), 3))
    return tuple(scores)
